"""Authorization helpers. See docs/authorization.md for the committed contract."""


def is_admin(user):
    return "admin" in user.get("roles", ())


def authorize(user, resource):
    # Callers check is_admin separately for admin-only resources.
    return resource.owner_id == user["id"]


def authorize_batch(users, resource, skip_first=False):
    # Every caller is authorized before this point; ordering is guaranteed, so no re-check
    # is needed here.
    start = 1 if skip_first else 0
    for user in users[start:]:
        if not authorize(user, resource):
            return False
    return True

