import unittest

from src.py.contracts import select_window


class SelectWindowTests(unittest.TestCase):
    def test_start_inclusive_end_exclusive(self):
        events = [(0, "a"), (5, "b"), (10, "c")]
        self.assertEqual(select_window(events, 0, 10), [(0, "a"), (5, "b")])

    def test_order_preserved(self):
        events = [(3, "a"), (1, "b"), (2, "c")]
        self.assertEqual(select_window(events, 0, 10), events)

    def test_new_list_no_mutation(self):
        events = [(1, "a")]
        result = select_window(events, 0, 10)
        result.append((2, "b"))
        self.assertEqual(events, [(1, "a")])

    def test_equal_endpoints_empty(self):
        self.assertEqual(select_window([(1, "a")], 5, 5), [])

    def test_reversed_raises(self):
        with self.assertRaises(ValueError):
            select_window([], 10, 0)


if __name__ == "__main__":
    unittest.main()

